package com.goldwithdrawamount;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(GoldWithdrawAmountConfig.GROUP)
public interface GoldWithdrawAmountConfig extends Config
{
    String GROUP = "goldwithdrawamount";

    @ConfigSection(
            name = "Bank withdrawals",
            description = "Warnings when taking coins out of the bank",
            position = 0
    )
    String withdrawSection = "withdrawSection";

    @ConfigSection(
            name = "Gold drops",
            description = "Notifications for coins dropped by NPCs/players and coins you pick up",
            position = 1
    )
    String dropSection = "dropSection";

    @ConfigSection(
            name = "Display",
            description = "Chat message and overlay settings",
            position = 2
    )
    String displaySection = "displaySection";

    // ------------------------------------------------------------------ Bank withdrawals
    // keyName "enabled" and "threshold" are kept from the original version so existing settings carry over.

    @ConfigItem(
            keyName = "enabled",
            name = "Warn on large withdrawals",
            description = "Warn when you withdraw at least the threshold amount of coins from your bank",
            position = 0,
            section = withdrawSection
    )
    default boolean withdrawWarning()
    {
        return true;
    }

    @ConfigItem(
            keyName = "threshold",
            name = "Withdrawal threshold",
            description = "Warn when withdrawing this many coins or more in one go",
            position = 1,
            section = withdrawSection
    )
    @Range(min = 1)
    default int withdrawThreshold()
    {
        return 10000;
    }

    // ------------------------------------------------------------------ Gold drops

    @ConfigItem(
            keyName = "notifyDrops",
            name = "Notify for gold drops",
            description = "Notify when an NPC you kill (e.g. a boss) or a player you kill (PKing) drops coins at or above the drop threshold",
            position = 0,
            section = dropSection
    )
    default boolean notifyDrops()
    {
        return false;
    }

    @ConfigItem(
            keyName = "dropThreshold",
            name = "Drop threshold",
            description = "Minimum coins in a single kill's loot to notify",
            position = 1,
            section = dropSection
    )
    @Range(min = 1)
    default int dropThreshold()
    {
        return 100000;
    }

    @ConfigItem(
            keyName = "notifyPickups",
            name = "Notify for gold pickups",
            description = "Notify when you pick coins up off the ground at or above the pickup threshold",
            position = 2,
            section = dropSection
    )
    default boolean notifyPickups()
    {
        return false;
    }

    @ConfigItem(
            keyName = "pickupThreshold",
            name = "Pickup threshold",
            description = "Minimum coins picked up in one go to notify",
            position = 3,
            section = dropSection
    )
    @Range(min = 1)
    default int pickupThreshold()
    {
        return 100000;
    }

    // ------------------------------------------------------------------ Display

    @ConfigItem(
            keyName = "chatMessage",
            name = "Chat message",
            description = "Post a message in the chatbox for each warning",
            position = 0,
            section = displaySection
    )
    default boolean chatMessage()
    {
        return true;
    }

    @ConfigItem(
            keyName = "overlayStyle",
            name = "Overlay style",
            description = "Panel box (movable, like other RuneLite overlays), floating text, both, or none",
            position = 1,
            section = displaySection
    )
    default OverlayStyle overlayStyle()
    {
        return OverlayStyle.PANEL;
    }

    @ConfigItem(
            keyName = "overlayDuration",
            name = "Overlay duration",
            description = "How long the overlay stays on screen (fades out over the last second)",
            position = 2,
            section = displaySection
    )
    @Units(Units.SECONDS)
    @Range(min = 1, max = 60)
    default int overlayDuration()
    {
        return 8;
    }

    @ConfigItem(
            keyName = "textSize",
            name = "Floating text size",
            description = "Font size of the floating text overlay",
            position = 3,
            section = displaySection
    )
    @Range(min = 12, max = 48)
    default int textSize()
    {
        return 20;
    }

    @Alpha
    @ConfigItem(
            keyName = "withdrawColor",
            name = "Withdrawal colour",
            description = "Colour used for withdrawal warnings",
            position = 4,
            section = displaySection
    )
    default Color withdrawColor()
    {
        return new Color(255, 60, 60);
    }

    @Alpha
    @ConfigItem(
            keyName = "dropColor",
            name = "Drop / pickup colour",
            description = "Colour used for gold drop and pickup notifications",
            position = 5,
            section = displaySection
    )
    default Color dropColor()
    {
        return new Color(255, 200, 40);
    }
}

package com.goldwithdrawamount;

import java.awt.AlphaComposite;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.util.QuantityFormatter;

/**
 * Standard RuneLite info panel: movable (Alt + drag), resizable, and matches other plugins' overlays.
 */
class GoldPanelOverlay extends OverlayPanel
{
    private static final int PANEL_WIDTH = 160;

    private final GoldWithdrawAmountPlugin plugin;
    private final GoldWithdrawAmountConfig config;

    @Inject
    private GoldPanelOverlay(GoldWithdrawAmountPlugin plugin, GoldWithdrawAmountConfig config)
    {
        super(plugin);
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
        setLayer(OverlayLayer.ABOVE_WIDGETS); // stay visible on top of the bank interface
        panelComponent.setPreferredSize(new Dimension(PANEL_WIDTH, 0));
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        final GoldAlert alert = plugin.getCurrentAlert();
        final long now = System.currentTimeMillis();
        if (alert == null || alert.isExpired(now) || !config.overlayStyle().showsPanel())
        {
            return null;
        }

        panelComponent.getChildren().add(TitleComponent.builder()
                .text(alert.getTitle())
                .color(alert.getColor())
                .build());

        panelComponent.getChildren().add(LineComponent.builder()
                .left("Amount:")
                .right(QuantityFormatter.formatNumber(alert.getAmount()))
                .rightColor(alert.getColor())
                .build());

        if (alert.getSource() != null)
        {
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("From:")
                    .right(alert.getSource())
                    .build());
        }

        panelComponent.getChildren().add(LineComponent.builder()
                .left("Threshold:")
                .right(QuantityFormatter.formatNumber(alert.getThreshold()))
                .build());

        final Composite original = graphics.getComposite();
        graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alert.opacity(now)));
        try
        {
            return super.render(graphics);
        }
        finally
        {
            graphics.setComposite(original);
        }
    }
}

package com.goldwithdrawamount;

import com.google.inject.Provides;
import java.awt.Color;
import java.util.Collection;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ItemDespawned;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.events.PlayerLootReceived;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.QuantityFormatter;

@Slf4j
@PluginDescriptor(
        name = "Gold Withdraw Warning",
        description = "Warns you when withdrawing more than your set gold threshold, with optional notifications for large gold drops and pickups.",
        tags = {"gold", "coins", "bank", "warning", "ironman", "drop", "loot", "pk"}
)
public class GoldWithdrawAmountPlugin extends Plugin
{
    /** Container changes and ground-item despawns for the same action arrive within this many ticks of each other. */
    private static final int MATCH_WINDOW_TICKS = 1;

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private ChatMessageManager chatMessageManager;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private GoldPanelOverlay panelOverlay;

    @Inject
    private GoldTextOverlay textOverlay;

    @Inject
    private GoldWithdrawAmountConfig config;

    /** The alert currently shown by the overlays (null when nothing to show). */
    @Getter
    private volatile GoldAlert currentAlert;

    // Last known coin totals; -1 means "unknown", so the first update only sets a baseline.
    private long lastInventoryGold = -1;
    private long lastBankGold = -1;

    // Half-matched events waiting for their partner (withdrawal = bank loss + inventory gain,
    // pickup = coins despawning next to you + inventory gain).
    private long pendingBankLoss;
    private int pendingBankLossTick;
    private long pendingBankGain;
    private int pendingBankGainTick;
    private long pendingWorldGain;
    private int pendingWorldGainTick;
    private long pendingDespawnCoins;
    private int pendingDespawnTick;

    @Provides
    GoldWithdrawAmountConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(GoldWithdrawAmountConfig.class);
    }

    @Override
    protected void startUp()
    {
        overlayManager.add(panelOverlay);
        overlayManager.add(textOverlay);

        clientThread.invoke(() ->
        {
            reset();
            if (client.getGameState() == GameState.LOGGED_IN)
            {
                lastInventoryGold = countGold(client.getItemContainer(InventoryID.INV));
                ItemContainer bank = client.getItemContainer(InventoryID.BANK);
                if (bank != null)
                {
                    lastBankGold = countGold(bank);
                }
            }
        });
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(panelOverlay);
        overlayManager.remove(textOverlay);
        currentAlert = null;
        clientThread.invoke(this::reset);
    }

    private void reset()
    {
        lastInventoryGold = -1;
        lastBankGold = -1;
        clearPending();
    }

    private void clearPending()
    {
        pendingBankLoss = 0;
        pendingBankGain = 0;
        pendingWorldGain = 0;
        pendingDespawnCoins = 0;
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        switch (event.getGameState())
        {
            case LOGIN_SCREEN:
            case HOPPING:
            case CONNECTION_LOST:
                // Containers are re-sent after login/hop; don't mistake that for gaining coins.
                reset();
                break;
            default:
                break;
        }
    }

    // ------------------------------------------------------------------ Withdrawals and pickups

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        final int containerId = event.getContainerId();
        final int tick = client.getTickCount();

        if (containerId == InventoryID.BANK)
        {
            final long gold = countGold(event.getItemContainer());
            if (lastBankGold >= 0 && gold < lastBankGold)
            {
                pendingBankLoss += lastBankGold - gold;
                pendingBankLossTick = tick;
                tryMatchWithdrawal();
            }
            lastBankGold = gold;
        }
        else if (containerId == InventoryID.INV)
        {
            final long gold = countGold(event.getItemContainer());
            if (lastInventoryGold >= 0 && gold > lastInventoryGold)
            {
                final long gain = gold - lastInventoryGold;
                if (isBankOpen())
                {
                    pendingBankGain += gain;
                    pendingBankGainTick = tick;
                    tryMatchWithdrawal();
                }
                else
                {
                    pendingWorldGain += gain;
                    pendingWorldGainTick = tick;
                    tryMatchPickup();
                }
            }
            lastInventoryGold = gold;
        }
    }

    @Subscribe
    public void onItemDespawned(ItemDespawned event)
    {
        if (event.getItem().getId() != ItemID.COINS)
        {
            return;
        }

        final Player player = client.getLocalPlayer();
        if (player == null || event.getTile().getWorldLocation().distanceTo(player.getWorldLocation()) > 1)
        {
            return; // not a stack you could have just picked up
        }

        pendingDespawnCoins += event.getItem().getQuantity();
        pendingDespawnTick = client.getTickCount();
        tryMatchPickup();
    }

    /**
     * A withdrawal is only counted when the bank loses coins AND the inventory gains coins
     * at the same time with the bank open. Shops, trades, pickups and logins can't trigger it.
     */
    private void tryMatchWithdrawal()
    {
        expireStale();
        if (pendingBankLoss <= 0 || pendingBankGain <= 0)
        {
            return;
        }

        final long amount = Math.min(pendingBankLoss, pendingBankGain);
        pendingBankLoss = 0;
        pendingBankGain = 0;

        if (config.withdrawWarning() && amount >= config.withdrawThreshold())
        {
            showAlert(GoldAlert.Type.WITHDRAWAL, "Large withdrawal",
                    "Withdrew " + QuantityFormatter.quantityToStackSize(amount) + " coins!",
                    amount, config.withdrawThreshold(), null, config.withdrawColor());
        }
    }

    /**
     * A pickup is counted when the inventory gains coins (bank closed) at the same time as
     * a coin stack disappears next to you.
     */
    private void tryMatchPickup()
    {
        expireStale();
        if (pendingWorldGain <= 0 || pendingDespawnCoins <= 0)
        {
            return;
        }

        final long amount = pendingWorldGain;
        pendingWorldGain = 0;
        pendingDespawnCoins = 0;

        if (config.notifyPickups() && amount >= config.pickupThreshold())
        {
            showAlert(GoldAlert.Type.PICKUP, "Gold picked up",
                    "Picked up " + QuantityFormatter.quantityToStackSize(amount) + " coins!",
                    amount, config.pickupThreshold(), null, config.dropColor());
        }
    }

    private void expireStale()
    {
        final int now = client.getTickCount();
        if (now - pendingBankLossTick > MATCH_WINDOW_TICKS)
        {
            pendingBankLoss = 0;
        }
        if (now - pendingBankGainTick > MATCH_WINDOW_TICKS)
        {
            pendingBankGain = 0;
        }
        if (now - pendingWorldGainTick > MATCH_WINDOW_TICKS)
        {
            pendingWorldGain = 0;
        }
        if (now - pendingDespawnTick > MATCH_WINDOW_TICKS)
        {
            pendingDespawnCoins = 0;
        }
    }

    private boolean isBankOpen()
    {
        final Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
        return bank != null && !bank.isHidden();
    }

    // ------------------------------------------------------------------ Kill loot (bosses / PKing)

    @Subscribe
    public void onNpcLootReceived(NpcLootReceived event)
    {
        final String name = event.getNpc() != null ? event.getNpc().getName() : null;
        handleLoot(event.getItems(), name);
    }

    @Subscribe
    public void onPlayerLootReceived(PlayerLootReceived event)
    {
        final String name = event.getPlayer() != null ? event.getPlayer().getName() : null;
        handleLoot(event.getItems(), name);
    }

    private void handleLoot(Collection<ItemStack> items, String sourceName)
    {
        if (!config.notifyDrops())
        {
            return;
        }

        long coins = 0;
        for (ItemStack stack : items)
        {
            if (stack.getId() == ItemID.COINS)
            {
                coins += stack.getQuantity();
            }
        }

        if (coins > 0 && coins >= config.dropThreshold())
        {
            showAlert(GoldAlert.Type.DROP, "Gold drop",
                    QuantityFormatter.quantityToStackSize(coins) + " coins dropped!",
                    coins, config.dropThreshold(), sourceName, config.dropColor());
        }
    }

    // ------------------------------------------------------------------ Output

    private void showAlert(GoldAlert.Type type, String title, String shortText,
                           long amount, long threshold, String source, Color color)
    {
        final long now = System.currentTimeMillis();
        currentAlert = new GoldAlert(type, title, shortText, amount, threshold, source, color,
                now, now + config.overlayDuration() * 1000L);

        if (config.chatMessage())
        {
            sendChat(type, amount, threshold, source, color);
        }
    }

    private void sendChat(GoldAlert.Type type, long amount, long threshold, String source, Color color)
    {
        final String coins = QuantityFormatter.formatNumber(amount);
        final String limit = QuantityFormatter.formatNumber(threshold);
        final String text;
        switch (type)
        {
            case WITHDRAWAL:
                text = "Warning: you withdrew " + coins + " coins (threshold " + limit + ").";
                break;
            case DROP:
                text = "Gold drop: " + coins + " coins" + (source != null ? " from " + source : "") + ".";
                break;
            case PICKUP:
            default:
                text = "You picked up " + coins + " coins.";
                break;
        }

        chatMessageManager.queue(QueuedMessage.builder()
                .type(ChatMessageType.GAMEMESSAGE)
                .runeLiteFormattedMessage(ColorUtil.wrapWithColorTag(text, color))
                .build());
    }

    private static long countGold(ItemContainer container)
    {
        if (container == null)
        {
            return 0;
        }

        long total = 0;
        for (Item item : container.getItems())
        {
            if (item.getId() == ItemID.COINS)
            {
                total += item.getQuantity();
            }
        }
        return total;
    }
}

package com.goldwithdrawamount;

import java.awt.Color;
import lombok.Value;

/**
 * One active warning shown by the overlays.
 */
@Value
class GoldAlert
{
    enum Type
    {
        WITHDRAWAL,
        DROP,
        PICKUP
    }

    Type type;
    /** Short headline, e.g. "Large withdrawal" */
    String title;
    /** Floating-text line, e.g. "Withdrew 1.2M coins!" */
    String shortText;
    long amount;
    long threshold;
    /** Optional extra detail, e.g. the NPC or player the drop came from. May be null. */
    String source;
    Color color;
    long createdAtMs;
    long expiresAtMs;

    boolean isExpired(long now)
    {
        return now >= expiresAtMs;
    }

    /**
     * 1.0 while fully visible, fading linearly to 0.0 over the final second.
     */
    float opacity(long now)
    {
        long remaining = expiresAtMs - now;
        if (remaining >= 1000)
        {
            return 1f;
        }
        return Math.max(0f, remaining / 1000f);
    }
}

package com.goldwithdrawamount;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Large outlined text, like the original overlay but drawn inside its own bounds
 * so it can be moved with Alt + drag and never gets clipped.
 */
class GoldTextOverlay extends Overlay
{
    private final GoldWithdrawAmountPlugin plugin;
    private final GoldWithdrawAmountConfig config;

    // Deriving a font is relatively expensive, so only do it when the size setting changes.
    private Font cachedFont;
    private int cachedSize = -1;

    @Inject
    private GoldTextOverlay(GoldWithdrawAmountPlugin plugin, GoldWithdrawAmountConfig config)
    {
        super(plugin);
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.TOP_CENTER);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(PRIORITY_HIGH);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        final GoldAlert alert = plugin.getCurrentAlert();
        final long now = System.currentTimeMillis();
        if (alert == null || alert.isExpired(now) || !config.overlayStyle().showsText())
        {
            return null;
        }

        graphics.setFont(getFont(config.textSize()));
        final FontMetrics metrics = graphics.getFontMetrics();
        final String text = alert.getShortText();

        // Draw from (1, ascent + 1) so the 1px outline stays inside the returned bounds.
        final int x = 1;
        final int y = metrics.getAscent() + 1;

        final Composite original = graphics.getComposite();
        graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alert.opacity(now)));
        try
        {
            graphics.setColor(Color.BLACK);
            graphics.drawString(text, x - 1, y);
            graphics.drawString(text, x + 1, y);
            graphics.drawString(text, x, y - 1);
            graphics.drawString(text, x, y + 1);
            graphics.drawString(text, x + 1, y + 1);

            graphics.setColor(alert.getColor());
            graphics.drawString(text, x, y);
        }
        finally
        {
            graphics.setComposite(original);
        }

        return new Dimension(metrics.stringWidth(text) + 2, metrics.getHeight() + 2);
    }

    private Font getFont(int size)
    {
        if (cachedFont == null || cachedSize != size)
        {
            cachedFont = FontManager.getRunescapeBoldFont().deriveFont((float) size);
            cachedSize = size;
        }
        return cachedFont;
    }
}

package com.goldwithdrawamount;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
public enum OverlayStyle
{
    PANEL("Panel box"),
    FLOATING_TEXT("Floating text"),
    BOTH("Both"),
    NONE("None");

    private final String name;

    boolean showsPanel()
    {
        return this == PANEL || this == BOTH;
    }

    boolean showsText()
    {
        return this == FLOATING_TEXT || this == BOTH;
    }

    @Override
    public String toString()
    {
        return name;
    }
}

